27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "title")
39	    private String title;
40	
41	    @Column(name = "address")
42	    @NotEmpty
43	    private String address;
44	
45	    @Column(name = "address_line1")
46	    private String addressLine1;
47	
48	    @Column(name = "address_line2")
49	    private String addressLine2;
50	
51	    @Column(name = "city")
52	    @NotEmpty
53	    private String city;
54	
55	    @Column(name = "telephone")
56	    @NotEmpty
57	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
58	    private String telephone;
59	
60	    @Column(name = "email")
61	    private String email;
62	
63	    @Column(name = "postcode")
64	    private String postcode;
65	
66	    @Column(name = "registration_date")
67	    private LocalDate registrationDate;
68	
69	    @Column(name = "birth_date")
70	    private LocalDate birthDate;
71	
72	    @Column(name = "customer_code")
73	    private String customerCode;
74	
75	    @Column(name = "household_id")
76	    private String householdId;
77	
78	    @Column(name = "namesake_count")
79	    private Integer namesakeCount;
80	
81	    @Column(name = "household_size")
82	    private Integer householdSize;
83	
84	    @Column(name = "membership_points")
85	    private Integer membershipPoints;
86	
87	    @Column(name = "membership_level")
88	    private Integer membershipLevel;
89	
90	    @Column(name = "bulk_signup_warning")
91	    private Boolean bulkSignupWarning;
92	
93	    @Column(name = "possible_duplicate")
94	    private Boolean possibleDuplicate;
95	
96	    @Column(name = "possible_duplicate_of")
97	    private Integer possibleDuplicateOf;
98	
99	    @Column(name = "deleted", nullable = false)
100	    private boolean deleted;
101	
102	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
103	    private Set<Pet> pets;
104	
105	    public String getTitle() {
106	        return this.title;
107	    }
108	
109	    public void setTitle(String title) {
110	        this.title = title;
111	    }
112	
113	    /**
114	     * The owner's salutation, derived on read from the owner's {@link #title} and last
115	     * name: {@code "<title> <lastName>"} when a title has been supplied, or just the last
116	     * name when it has not.
117	     */
118	    @Transient
119	    public String getSalutation() {
120	        if (this.title == null || this.title.isBlank()) {
121	            return getLastName();
122	        }
123	        return this.title + " " + getLastName();
124	    }
125	
126	    /**
127	     * The owner's canonical API path, formatted {@code /api/owners/<id>}, e.g.
128	     * {@code "/api/owners/1"}. Derived on read from the owner's {@link #getId() id};
129	     * {@code null} until the owner has been persisted and assigned an id.
130	     */
131	    @Transient
132	    public String getSelfLink() {
133	        if (getId() == null) {
134	            return null;
135	        }
136	        return "/api/owners/" + getId();
137	    }
138	
139	    public String getAddress() {
140	        return this.address;
141	    }
142	
143	    public void setAddress(String address) {
144	        this.address = address;
145	    }
146	
147	    /**
148	     * The first line of the owner's structured address, when supplied. Preferred over the
149	     * flat {@link #getAddress() address} and used to compose it; {@code null} for owners
150	     * created from the flat address form.
151	     */
152	    public String getAddressLine1() {
153	        return this.addressLine1;
154	    }
155	
156	    public void setAddressLine1(String addressLine1) {
157	        this.addressLine1 = addressLine1;
158	    }
159	
160	    /**
161	     * The optional second line of the owner's structured address; {@code null} when absent.
162	     * When present it is appended to {@link #getAddressLine1() addressLine1} to compose the
163	     * {@link #getAddress() address}.
164	     */
165	    public String getAddressLine2() {
166	        return this.addressLine2;
167	    }
168	
169	    public void setAddressLine2(String addressLine2) {
170	        this.addressLine2 = addressLine2;
171	    }
172	
173	    public String getCity() {
174	        return this.city;
175	    }
176	
177	    public void setCity(String city) {
178	        this.city = city;
179	    }
180	
181	    public String getTelephone() {
182	        return this.telephone;
183	    }
184	
185	    public void setTelephone(String telephone) {
186	        this.telephone = telephone;
187	    }
188	
189	    /**
190	     * The owner's stored E.164 {@link #telephone} formatted for humans: the country code, a
191	     * space, then the national digits grouped in threes, e.g. {@code "+61 412 345 678"}.
192	     * Derived on read; {@code null} until a telephone has been set.
193	     */
194	    @Transient
195	    public String getTelephoneDisplay() {
196	        return TelephoneDisplay.format(this.telephone);
197	    }
198	
199	    public String getEmail() {
200	        return this.email;
201	    }
202	
203	    public void setEmail(String email) {
204	        this.email = email;
205	    }
206	
207	    public String getPostcode() {
208	        return this.postcode;
209	    }
210	
211	    public void setPostcode(String postcode) {
212	        this.postcode = postcode;
213	    }
214	
215	    public LocalDate getRegistrationDate() {
216	        return this.registrationDate;
217	    }
218	
219	    public void setRegistrationDate(LocalDate registrationDate) {
220	        this.registrationDate = registrationDate;
221	    }
222	
223	    public LocalDate getBirthDate() {
224	        return this.birthDate;
225	    }
226	
227	    public void setBirthDate(LocalDate birthDate) {
228	        this.birthDate = birthDate;
229	    }
230	
231	    /**
232	     * The owner's {@link AgeBand age band} as of their {@link #registrationDate}, derived on
233	     * read from the owner's {@link #birthDate}. {@code null} until both the birth date and the
234	     * registration date have been supplied.
235	     */
236	    @Transient
237	    public String getAgeBand() {
238	        if (this.birthDate == null || this.registrationDate == null) {
239	            return null;
240	        }
241	        return AgeBand.asOf(this.birthDate, this.registrationDate).name();
242	    }
243	
244	    public String getCustomerCode() {
245	        return this.customerCode;
246	    }
247	
248	    public void setCustomerCode(String customerCode) {
249	        this.customerCode = customerCode;
250	    }
251	
252	    /**
253	     * The owner's fiscal year, formatted {@code FY<YY>} where {@code YY} is the last two
254	     * digits of the {@link FiscalYear fiscal year} the {@code registrationDate} falls in
255	     * (the fiscal year starts on 1 July), e.g. {@code "FY26"}. Derived on read from the
256	     * owner's registration date; {@code null} until it has been assigned.
257	     */
258	    @Transient
259	    public String getFiscalYear() {
260	        if (this.registrationDate == null) {
261	            return null;
262	        }
263	        return FiscalYear.labelOf(this.registrationDate);
264	    }
265	
266	    /**
267	     * The owner's membership number, formatted {@code <customerCode>-M<YY>} where
268	     * {@code YY} is the last two digits of the {@link FiscalYear fiscal year} the
269	     * {@code registrationDate} falls in (the fiscal year starts on 1 July), e.g.
270	     * {@code "NSW-1A2B3C4D-M26"}. Derived from the owner's own fields; {@code null} until
271	     * both the customer code and registration date have been assigned.
272	     */
273	    @Transient
274	    public String getMembershipNumber() {
275	        if (this.customerCode == null || this.registrationDate == null) {
276	            return null;
277	        }
278	        return String.format("%s-M%02d", this.customerCode, FiscalYear.startYearOf(this.registrationDate) % 100);
279	    }
280	
281	    /**
282	     * The owner's check digit: a single {@link Luhn} check digit computed over the digits
283	     * of the owner's {@link #customerCode}. {@code null} until the customer code has been
284	     * assigned.
285	     */
286	    @Transient
287	    public Integer getCheckDigit() {
288	        if (this.customerCode == null) {
289	            return null;
290	        }
291	        return Luhn.checkDigit(this.customerCode);
292	    }
293	
294	    /**
295	     * The owner's region: the canonical region derived from the owner's {@link #postcode}
296	     * via the fixed {@link RegionPostcodeTable}, falling back to the owner's {@link #city}
297	     * via the fixed {@link CityRegionTable} when the postcode is absent or in no known
298	     * range, or {@code "UNKNOWN"} when neither yields a region. This is the {@code REGION}
299	     * segment of the owner's {@link #getCustomerCode() customer code}.
300	     */
301	    @Transient
302	    public String getRegion() {
303	        return RegionPostcodeTable.regionOf(this.postcode)
304	            .orElseGet(() -> CityRegionTable.regionOf(this.city));
305	    }
306	
307	    /**
308	     * The owner's locality, read from its region-and-hash identity: the {@code REGION}
309	     * segment (everything before the first {@code '-'}) of the owner's
310	     * {@link #getCustomerCode() customer code}. Falls back to the owner's live
311	     * {@link #getRegion() region} until a customer code has been assigned.
312	     */
313	    @Transient
314	    public String getLocality() {
315	        if (this.customerCode == null) {
316	            return getRegion();
317	        }
318	        int dash = this.customerCode.indexOf('-');
319	        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
320	    }
321	
322	    /**
323	     * The owner's IANA timezone name, derived on read from the owner's
324	     * {@link #getLocality() locality} via the fixed {@link RegionTimezoneTable}, e.g.
325	     * {@code "Australia/Sydney"} for {@code NSW}. {@code null} when the locality has no
326	     * timezone in the table.
327	     */
328	    @Transient
329	    public String getTimezone() {
330	        return RegionTimezoneTable.timezoneOf(getLocality());
331	    }
332	
333	    /**
334	     * The owner's preferred contact channel, derived on read from the owner's own
335	     * fields: {@code "EMAIL"} when the owner has an email address, otherwise
336	     * {@code "PHONE"}.
337	     */
338	    @Transient
339	    public String getContactPreference() {
340	        return (this.email == null || this.email.isBlank()) ? "PHONE" : "EMAIL";
341	    }
342	
343	    /**
344	     * The owner's identity key: the single value used to detect duplicate owners on
345	     * create. It joins the owner's (already normalized) telephone, email and household id
346	     * with {@code '|'} — {@code <telephone>|<email>|<householdId>} — a missing email or
347	     * household id contributing an empty segment. Two owners are duplicates only when
348	     * their whole identity keys are equal.
349	     */
350	    @Transient
351	    public String getIdentityKey() {
352	        return orEmpty(this.telephone) + "|" + orEmpty(this.email) + "|" + orEmpty(this.householdId);
353	    }
354	
355	    private static String orEmpty(String value) {
356	        return value == null ? "" : value;
357	    }
358	
359	    public String getHouseholdId() {
360	        return this.householdId;
361	    }
362	
363	    public void setHouseholdId(String householdId) {
364	        this.householdId = householdId;
365	    }
366	
367	    public Integer getNamesakeCount() {
368	        return this.namesakeCount;
369	    }
370	
371	    public void setNamesakeCount(Integer namesakeCount) {
372	        this.namesakeCount = namesakeCount;
373	    }
374	
375	    public Integer getHouseholdSize() {
376	        return this.householdSize;
377	    }
378	
379	    public void setHouseholdSize(Integer householdSize) {
380	        this.householdSize = householdSize;
381	    }
382	
383	    /**
384	     * The owner's membership points, assigned on create by tallying the owner's standing:
385	     * points for having an email address, for having no namesakes, for a large household and
386	     * for tenure (see {@code MembershipLevelAssigner}). The points determine the owner's
387	     * {@link #getMembershipLevel() membership level}.
388	     */
389	    public Integer getMembershipPoints() {
390	        return this.membershipPoints;
391	    }
392	
393	    public void setMembershipPoints(Integer membershipPoints) {
394	        this.membershipPoints = membershipPoints;
395	    }
396	
397	    /**
398	     * The owner's membership level, a number from 1 to 4 assigned on create by banding the
399	     * owner's {@link #getMembershipPoints() membership points} (see
400	     * {@code MembershipLevelAssigner}).
401	     */
402	    public Integer getMembershipLevel() {
403	        return this.membershipLevel;
404	    }
405	
406	    public void setMembershipLevel(Integer membershipLevel) {
407	        this.membershipLevel = membershipLevel;
408	    }
409	
410	    public Boolean getBulkSignupWarning() {
411	        return this.bulkSignupWarning;
412	    }
413	
414	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
415	        this.bulkSignupWarning = bulkSignupWarning;
416	    }
417	
418	    /**
419	     * Whether this owner, when created, softly matched an already-stored owner: one that
420	     * shares its last name and postcode but carries a different telephone. Assigned on
421	     * create; when {@code true}, {@link #getPossibleDuplicateOf()} identifies the matched
422	     * owner.
423	     */
424	    public Boolean getPossibleDuplicate() {
425	        return this.possibleDuplicate;
426	    }
427	
428	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
429	        this.possibleDuplicate = possibleDuplicate;
430	    }
431	
432	    /**
433	     * The id of the already-stored owner this owner softly matched on create (same last
434	     * name and postcode, different telephone), or {@code null} when it matched none.
435	     */
436	    public Integer getPossibleDuplicateOf() {
437	        return this.possibleDuplicateOf;
438	    }
439	
440	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
441	        this.possibleDuplicateOf = possibleDuplicateOf;
442	    }
443	
444	    /**
445	     * Whether this owner has been soft-deleted. A newly created owner is {@code false};
446	     * {@code DELETE /api/owners/{id}} flags it {@code true} while retaining the record. Owners
447	     * flagged deleted are ignored by the create endpoint's duplicate and identity checks.
448	     */
449	    public boolean isDeleted() {
450	        return this.deleted;
451	    }
452	
453	    public void setDeleted(boolean deleted) {
454	        this.deleted = deleted;
455	    }
456	
457	    protected Set<Pet> getPetsInternal() {
458	        if (this.pets == null) {
459	            this.pets = new HashSet<>();
460	        }
461	        return this.pets;
462	    }
463	
464	    protected void setPetsInternal(Set<Pet> pets) {
465	        this.pets = pets;
466	    }
467	
468	    public List<Pet> getPets() {
469	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
470	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
471	        return Collections.unmodifiableList(sortedPets);
472	    }
473	
474	    public void setPets(List<Pet> pets) {
475	        this.pets = new HashSet<>(pets);
476	    }
477	
478	    public void addPet(Pet pet) {
479	        getPetsInternal().add(pet);
480	        pet.setOwner(this);
481	    }
482	
483	    /**
484	     * Return the Pet with the given name, or null if none found for this Owner.
485	     *
486	     * @param name to test
487	     * @return true if pet name is already in use
488	     */
489	    public Pet getPet(String name) {
490	        return getPet(name, false);
491	    }
492	
493	    /**
494	     * Return the Pet with the given name, or null if none found for this Owner.
495	     *
496	     * @param name to test
497	     * @return true if pet name is already in use
498	     */
499	    public Pet getPet(String name, boolean ignoreNew) {
500	        name = name.toLowerCase();
501	        for (Pet pet : getPetsInternal()) {
502	            if (!ignoreNew || !pet.isNew()) {
503	                String compName = pet.getName();
504	                compName = compName.toLowerCase();
505	                if (compName.equals(name)) {
506	                    return pet;
507	                }
508	            }
509	        }
510	        return null;
511	    }
512	
513	    public Pet getPet(Integer petId) {
514	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
515	    }
516	
517	    @Override
518	    public String toString() {
519	        return new ToStringCreator(this)
520	
521	            .append("id", this.getId())
522	            .append("new", this.isNew())
523	            .append("lastName", this.getLastName())
524	            .append("firstName", this.getFirstName())
525	            .append("address", this.address)
526	            .append("city", this.city)
527	            .append("telephone", this.telephone)
528	            .append("email", this.email)
529	            .append("registrationDate", this.registrationDate)
530	            .append("customerCode", this.customerCode)
531	            .toString();
532	    }
533	}
