187	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
188	    @Override
189	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
190	        if (StringUtils.hasText(idempotencyKey)) {
191	            Owner original = this.idempotentOwnerStore.find(idempotencyKey)
192	                .map(this.clinicService::findOwnerById)
193	                .orElse(null);
194	            if (original != null) {
195	                return new ResponseEntity<>(ownerMapper.toOwnerDto(original), HttpStatus.OK);
196	            }
197	        }
198	        HttpHeaders headers = new HttpHeaders();
199	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
200	        this.registrationDateAssigner.assign(owner);
201	        if (this.cityCapacityChecker.isCityAtCapacity(owner)) {
202	            return new ResponseEntity<>(HttpStatus.CONFLICT);
203	        }
204	        if (this.dailyRegistrationLimiter.isDailyLimitReached(owner.getRegistrationDate())) {
205	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
206	        }
207	        this.householdAssigner.assign(owner);
208	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
209	        boolean householdDuplicate = this.householdDuplicateChecker.isDuplicate(owner);
210	        if (householdDuplicate && !sharesHousehold) {
211	            return new ResponseEntity<>(HttpStatus.CONFLICT);
212	        }
213	        if (this.identityDuplicateChecker.isDuplicate(owner)) {
214	            return new ResponseEntity<>(HttpStatus.CONFLICT);
215	        }
216	        boolean declaredHouseholdMember = householdDuplicate && sharesHousehold;
217	        this.householdSizeAssigner.assign(owner);
218	        this.customerCodeAssigner.assign(owner);
219	        this.namesakeCounter.assign(owner);
220	        this.membershipLevelAssigner.assign(owner);
221	        this.bulkSignupWarningAssigner.assign(owner);
222	        this.possibleDuplicateAssigner.assign(owner, declaredHouseholdMember);
223	        this.clinicService.saveOwner(owner);
224	        if (StringUtils.hasText(idempotencyKey)) {
225	            this.idempotentOwnerStore.remember(idempotencyKey, owner);
226	        }
227	        this.ownerCreationAuditLogger.logCreated(owner);
228	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
229	        headers.setLocation(UriComponentsBuilder.newInstance()
230	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
231	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
232	    }
