18	
19	import org.springframework.samples.petclinic.model.Owner;
20	import org.springframework.stereotype.Component;
21	
22	/**
23	 * Assigns, on create, the owner's membership points and the numeric membership level they
24	 * band into.
25	 * <p>
26	 * Points start at zero and accrue from the owner's standing: {@link #EMAIL_POINTS} when the
27	 * owner has an email address, {@link #NO_NAMESAKE_POINTS} when the owner has no namesakes
28	 * ({@code namesakeCount} is 0), {@link #LARGE_HOUSEHOLD_POINTS} for a household of
29	 * {@link #LARGE_HOUSEHOLD_MIN_SIZE} or more, and {@link #TENURE_POINTS} for tenure of more
30	 * than {@link #QUALIFYING_TENURE_FISCAL_YEARS} fiscal years. The total bands into a level of 1 (0-1 points),
31	 * 2 (2-3), 3 (4-5) or 4 (6 or more). A newly created owner has not yet accrued any tenure, so
32	 * on create the tenure points are never earned. As it reads the owner's namesake count and
33	 * household size, this must be assigned after {@link NamesakeCounter} and
34	 * {@link HouseholdSizeAssigner}, and before the owner is saved.
35	 */
36	@Component
37	public class MembershipLevelAssigner {
38	
39	    /** Points awarded when the owner has an email address. */
40	    static final int EMAIL_POINTS = 2;
41	
42	    /** Points awarded when the owner has no namesakes ({@code namesakeCount} is 0). */
43	    static final int NO_NAMESAKE_POINTS = 1;
44	
45	    /** Points awarded for a household of {@link #LARGE_HOUSEHOLD_MIN_SIZE} or more. */
46	    static final int LARGE_HOUSEHOLD_POINTS = 2;
47	
48	    /** Points awarded for tenure of more than {@link #QUALIFYING_TENURE_FISCAL_YEARS} fiscal years. */
49	    static final int TENURE_POINTS = 3;
50	
51	    /** Household size, in members, at or above which {@link #LARGE_HOUSEHOLD_POINTS} apply. */
52	    static final int LARGE_HOUSEHOLD_MIN_SIZE = 3;
53	
54	    /** Tenure, in elapsed fiscal years, an owner must exceed to earn the {@link #TENURE_POINTS}. */
55	    static final int QUALIFYING_TENURE_FISCAL_YEARS = 1;
56	
57	    /**
58	     * Assigns {@code owner}'s membership points and the level they band into. Call this after
59	     * the namesake count and household size have been assigned and before the owner is saved.
60	     *
61	     * @param owner the owner being created
62	     */
63	    public void assign(Owner owner) {
64	        int points = points(owner);
65	        owner.setMembershipPoints(points);
66	        owner.setMembershipLevel(levelForPoints(points));
67	    }
68	
69	    /** The owner's total membership points, tallied from its standing. */
70	    private int points(Owner owner) {
71	        int points = 0;
72	        if (hasEmail(owner)) {
73	            points += EMAIL_POINTS;
74	        }
75	        if (hasNoNamesakes(owner)) {
76	            points += NO_NAMESAKE_POINTS;
77	        }
78	        if (hasLargeHousehold(owner)) {
79	            points += LARGE_HOUSEHOLD_POINTS;
80	        }
81	        if (hasQualifyingTenure(owner)) {
82	            points += TENURE_POINTS;
83	        }
84	        return points;
85	    }
86	
87	    /** Bands a point total into a membership level: 1 (0-1), 2 (2-3), 3 (4-5), 4 (6 or more). */
88	    private int levelForPoints(int points) {
89	        if (points >= 6) {
90	            return 4;
91	        }
92	        if (points >= 4) {
93	            return 3;
94	        }
95	        if (points >= 2) {
96	            return 2;
97	        }
98	        return 1;
99	    }
100	
101	    private boolean hasEmail(Owner owner) {
102	        return owner.getEmail() != null && !owner.getEmail().isBlank();
103	    }
104	
105	    private boolean hasNoNamesakes(Owner owner) {
106	        return owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
107	    }
108	
109	    private boolean hasLargeHousehold(Owner owner) {
110	        return owner.getHouseholdSize() != null && owner.getHouseholdSize() >= LARGE_HOUSEHOLD_MIN_SIZE;
111	    }
112	
113	    /**
114	     * Whether the owner's tenure exceeds the {@link #QUALIFYING_TENURE_FISCAL_YEARS} the tenure
115	     * points require. A newly created owner has not yet accrued any tenure, so on create this is
116	     * always {@code false} and a new owner never earns the tenure points.
117	     */
118	    private boolean hasQualifyingTenure(Owner owner) {
119	        return tenureFiscalYears(owner) > QUALIFYING_TENURE_FISCAL_YEARS;
120	    }
121	
122	    /** The whole fiscal years the owner has been a member; zero for an owner being created. */
123	    private long tenureFiscalYears(Owner owner) {
124	        return 0L;
125	    }
126	}
