21	
22	/**
23	 * Tags an owner, on create, with its household's stable shared identifier. The identifier is
24	 * derived deterministically from the owner's last name and postcode (see
25	 * {@link HouseholdMatcher}), so every owner in the same household ends up carrying the same
26	 * value without any explicit linking or back-filling step.
27	 */
28	@Component
29	public class HouseholdAssigner {
30	
31	    private final HouseholdMatcher householdMatcher;
32	
33	    public HouseholdAssigner(HouseholdMatcher householdMatcher) {
34	        this.householdMatcher = householdMatcher;
35	    }
36	
37	    /**
38	     * Tags {@code candidate} with its household's shared identifier. The candidate is not
39	     * saved here; the caller persists it as part of the create.
40	     *
41	     * @param candidate the owner being created
42	     * @return the shared household identifier applied to the candidate
43	     */
44	    public String assign(Owner candidate) {
45	        String householdId = householdMatcher.householdId(candidate);
46	        candidate.setHouseholdId(householdId);
47	        return householdId;
48	    }
49	}
