17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import org.springframework.samples.petclinic.model.Owner;
20	import org.springframework.samples.petclinic.service.ClinicService;
21	import org.springframework.stereotype.Component;
22	
23	/**
24	 * Records, on create, how many owners belong to the new owner's household once this create
25	 * completes: the already-stored owners sharing its {@code householdId} plus the owner itself.
26	 * <p>
27	 * The count drives the {@code GOLD} membership tier, so it must be assigned after the
28	 * household identifier has been resolved (see {@link HouseholdAssigner}) but before the owner
29	 * is saved. An owner that does not belong to a shared household (no {@code householdId}) is
30	 * its own single-member household.
31	 */
32	@Component
33	public class HouseholdSizeAssigner {
34	
35	    private final ClinicService clinicService;
36	
37	    public HouseholdSizeAssigner(ClinicService clinicService) {
38	        this.clinicService = clinicService;
39	    }
40	
41	    /**
42	     * Assigns {@code owner}'s household size: the number of already-stored owners sharing its
43	     * {@code householdId}, plus one for the owner being created. Call this after the household
44	     * identifier has been assigned and before the owner is saved so it does not count itself.
45	     *
46	     * @param owner the owner being created
47	     */
48	    public void assign(Owner owner) {
49	        String householdId = owner.getHouseholdId();
50	        if (householdId == null) {
51	            owner.setHouseholdSize(1);
52	            return;
53	        }
54	        long existing = clinicService.findAllOwners().stream()
55	            .filter(member -> householdId.equals(member.getHouseholdId()))
56	            .count();
57	        owner.setHouseholdSize(Math.toIntExact(existing + 1));
58	    }
59	}
