17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import java.util.List;
20	import java.util.Locale;
21	import java.util.regex.Pattern;
22	
23	import org.springframework.samples.petclinic.model.Owner;
24	import org.springframework.samples.petclinic.model.Sha256Hex;
25	import org.springframework.samples.petclinic.service.ClinicService;
26	import org.springframework.stereotype.Component;
27	
28	/**
29	 * Groups owners into households and derives a household's stable shared identifier.
30	 * <p>
31	 * Two owners belong to the same household when they carry the same last name and the same
32	 * postcode. The last name is compared leniently: surrounding whitespace is trimmed, internal
33	 * runs of whitespace are collapsed to a single space and letters are compared without
34	 * regard to case, so values that differ only in spacing or capitalisation are treated as
35	 * equal. The postcode is compared verbatim. Because the identifier is derived
36	 * deterministically from these two fields, owners sharing a last name and postcode resolve
37	 * to the same household without any explicit linking step.
38	 */
39	@Component
40	public class HouseholdMatcher {
41	
42	    /** Runs of whitespace collapsed to a single space before comparison. */
43	    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
44	
45	    private final ClinicService clinicService;
46	
47	    public HouseholdMatcher(ClinicService clinicService) {
48	        this.clinicService = clinicService;
49	    }
50	
51	    /**
52	     * Returns the already-stored owners that share {@code candidate}'s household under the
53	     * lenient comparison described above. The candidate itself is not yet stored, so it is
54	     * never included; owners flagged deleted are excluded.
55	     *
56	     * @param candidate the owner being created
57	     * @return existing household members, possibly empty
58	     */
59	    public List<Owner> findMembers(Owner candidate) {
60	        String key = householdKey(candidate);
61	        return clinicService.findAllOwners().stream()
62	            .filter(existing -> !existing.isDeleted())
63	            .filter(existing -> householdKey(existing).equals(key))
64	            .toList();
65	    }
66	
67	    /**
68	     * The stable identifier for {@code candidate}'s household: the first 12 hex characters of
69	     * the SHA-256 digest of its (normalised) last name and postcode, joined by {@code '|'}, so
70	     * that every owner sharing a last name and postcode resolves to the same value.
71	     *
72	     * @param candidate an owner in the household
73	     * @return a non-blank household identifier
74	     */
75	    public String householdId(Owner candidate) {
76	        return Sha256Hex.prefix(householdKey(candidate), 12);
77	    }
78	
79	    private String householdKey(Owner owner) {
80	        return normalizeName(owner.getLastName()) + "|" + orEmpty(owner.getPostcode());
81	    }
82	
83	    private String normalizeName(String value) {
84	        if (value == null) {
85	            return "";
86	        }
87	        return WHITESPACE.matcher(value.trim()).replaceAll(" ").toLowerCase(Locale.ROOT);
88	    }
89	
90	    private String orEmpty(String value) {
91	        return value == null ? "" : value;
92	    }
93	}
