public void assign(Owner owner) {
    int points = points(owner);
    owner.setMembershipPoints(points);
    owner.setMembershipLevel(cappedByHousehold(levelForPoints(points), owner));
}

/**
 * Caps {@code level} at one above the highest level held among {@code owner}'s existing
 * household members. When the owner has no existing household member the level is returned
 * unchanged.
 */
private int cappedByHousehold(int level, Owner owner) {
    OptionalInt highest = highestHouseholdLevel(owner);
    if (highest.isEmpty()) {
        return level;
    }
    return Math.min(level, highest.getAsInt() + HOUSEHOLD_LEVEL_HEADROOM);
}

/** The highest membership level currently held among the owner's existing household members. */
private OptionalInt highestHouseholdLevel(Owner owner) {
    return householdMatcher.findMembers(owner).stream()
        .map(Owner::getMembershipLevel)
        .filter(Objects::nonNull)
        .mapToInt(Integer::intValue)
        .max();
}

